code:
  language: csharp
  harness: statements
  source: |
    try
    {
        PlaceOrder(42, 0);
    }
    catch (OrderException ex)
    {
        Console.WriteLine($"Order {ex.OrderId}: {ex.Message}");
    }

    static void PlaceOrder(int orderId, int quantity)
    {
        if (quantity <= 0)
        {
            throw new OrderException(orderId, "Quantity must be positive");
        }
    }

    class OrderException : Exception
    {
        public OrderException(int orderId, string message)
        {
            OrderId = orderId;
        }

        public int OrderId { get; }
    }
